-- Proofly secure admin layer. Run after supabase.sql.
create table if not exists public.admin_roles (user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in('admin','moderator','analyst')), created_at timestamptz not null default now());
create table if not exists public.risk_entities (id uuid primary key default gen_random_uuid(),identifier text not null,normalized_identifier text not null,platform text not null default 'unknown',severity text not null check(severity in('limited','suspicious','high')),status text not null default 'active' check(status in('active','resolved','false_positive')),title text not null,detail text,source text not null default 'user_report',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_risk_entities_normalized on public.risk_entities(normalized_identifier);
create table if not exists public.fraud_reports (id uuid primary key default gen_random_uuid(),reporter_id uuid not null references auth.users(id) on delete cascade,identifier text,platform text,category text not null,description text not null,amount numeric,currency text,proof_id text,status text not null default 'submitted' check(status in('submitted','under_review','needs_info','restricted','resolved','closed')),priority text not null default 'normal' check(priority in('low','normal','high','critical')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.user_flags (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,reason text not null,severity text not null check(severity in('low','medium','high','critical')),status text not null default 'open' check(status in('open','resolved')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.admin_audit_logs (id bigint generated always as identity primary key,admin_id uuid not null references auth.users(id),action text not null,target_type text,target_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_roles where user_id=auth.uid() and role in('admin','moderator','analyst')); $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_roles where user_id=auth.uid() and role='admin'); $$;
alter table public.admin_roles enable row level security; alter table public.risk_entities enable row level security; alter table public.fraud_reports enable row level security; alter table public.user_flags enable row level security; alter table public.admin_audit_logs enable row level security;
drop policy if exists "Users can read own role" on public.admin_roles; create policy "Users can read own role" on public.admin_roles for select using(auth.uid()=user_id or public.is_admin());
drop policy if exists "Admins manage roles" on public.admin_roles; create policy "Admins manage roles" on public.admin_roles for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "Anyone can read active risk signals" on public.risk_entities; create policy "Anyone can read active risk signals" on public.risk_entities for select using(status='active' or public.is_staff());
drop policy if exists "Staff manage risk signals" on public.risk_entities; create policy "Staff manage risk signals" on public.risk_entities for all using(public.is_staff()) with check(public.is_staff());
drop policy if exists "Users create own fraud reports" on public.fraud_reports; create policy "Users create own fraud reports" on public.fraud_reports for insert with check(auth.uid()=reporter_id);
drop policy if exists "Users read own fraud reports" on public.fraud_reports; create policy "Users read own fraud reports" on public.fraud_reports for select using(auth.uid()=reporter_id or public.is_staff());
drop policy if exists "Staff update fraud reports" on public.fraud_reports; create policy "Staff update fraud reports" on public.fraud_reports for update using(public.is_staff()) with check(public.is_staff());
drop policy if exists "Staff manage user flags" on public.user_flags; create policy "Staff manage user flags" on public.user_flags for all using(public.is_staff()) with check(public.is_staff());
drop policy if exists "Staff insert admin audit" on public.admin_audit_logs; create policy "Staff insert admin audit" on public.admin_audit_logs for insert with check(public.is_staff() and auth.uid()=admin_id);
drop policy if exists "Staff read admin audit" on public.admin_audit_logs; create policy "Staff read admin audit" on public.admin_audit_logs for select using(public.is_staff());
